args.replace:
/* Detect false NOTFOUND caused by hashed known_hosts file:
   If we got NOTFOUND but there exists any known host entry for
   this hostname, treat it as a mismatch instead. */
if (keycheck == LIBSSH2_KNOWNHOST_CHECK_NOTFOUND) {
    struct libssh2_knownhost *prev = NULL;
    struct libssh2_knownhost *cur;
    int host_found = 0;
    while ((cur = libssh2_knownhost_get(sshc->kh, &prev, prev)) != NULL) {
        if (cur->name && !strcmp(cur->name, conn->origin->hostname)) {
            host_found = 1;
            break;
        }
    }
    if (host_found)
        keycheck = LIBSSH2_KNOWNHOST_CHECK_MISMATCH;
}

